SCENE w=480 h=480 fit=contain
# widget header hdr1 {"x":24,"y":0,"w":432,"h":64,"title":"Airlock","clock":false,"counts":true,"keys":{}}
G id=hdr1 {
    R x=24.5 y=0.5 w=431 h=63 f=#1A1A1A s=#4A4A4A sw=1
    G v==gt($hdr1_crit,0) {
        C cx=380 cy=32 rx=8 ry=8 f=#EF5350
        T x=398 y=15 w=40 h=34 text="{$hdr1_crit:%.0f}" size=24 f=#F2F2F2 align=right valign=middle
    }
    G v==gt($hdr1_warn,0) {
        C cx=298 cy=32 rx=8 ry=8 f=#F0B429
        T x=316 y=15 w=40 h=34 text="{$hdr1_warn:%.0f}" size=24 f=#F2F2F2 align=right valign=middle
    }
    T x=42 y=4 w=222 h=56 text=Airlock size=30 weight=bold f=#F2F2F2 valign=middle fit=ellipsis
}
# widget readoutrow row1 {"x":24,"y":90,"w":432,"h":50,"name":"Room pressure kPa","fmt1":"%.1f","fmt2":"","w1":120,"w2":80,"keys":{}}
G id=row1 {
    R x=24 y=90 w=432 h=50 rx=4 f=#2C2C2C
    C v==1-eq($row1_st,1)-eq($row1_st,2)-eq($row1_st,3) cx=46 cy=115 rx=8 ry=8 f=#9A9A9A
    C v==eq($row1_st,1) cx=46 cy=115 rx=8 ry=8 f=#4CC38A
    C v==eq($row1_st,2) cx=46 cy=115 rx=8 ry=8 f=#F0B429
    C v==eq($row1_st,3) cx=46 cy=115 rx=8 ry=8 f=#EF5350
    T x=64 y=90 w=248 h=50 text="Room pressure kPa" size=24 f=#F2F2F2 valign=middle fit=ellipsis
    T x=322 y=90 w=120 h=50 text="{$row1_r1:%.1f}" size=28 f==if(eq($row1_st,2),#F0B429,if(eq($row1_st,3),#EF5350,#F2F2F2)) align=right valign=middle fit=ellipsis
}
# widget button btn1 {"x":24,"y":160,"w":210,"h":54,"states":[{"label":"Open inner","variant":"secondary","key":0}],"canDisable":false,"canSelect":false,"keys":{}}
G id=btn1 {
    R id=btn1_hit click=1 x=24 y=160 w=210 h=54
    R x=24.5 y=160.5 w=209 h=53 rx=3.5 f=#2C2C2C s=#4A4A4A sw=1 fo==1-0.25*down
    T x=42 y=160 w=174 h=54 text="Open inner" size=22 weight=bold f=#F2F2F2 align=center valign=middle fit=ellipsis
}
